import { Checkbox, cn, DensityProvider, Table, TableCaption, TableHead, TableHeader, TableRow, type MoreMenuAction, type TableDensity, useDensity, useI18n } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';
import { PaginationFooter } from '../pagination-footer/PaginationFooter';
import { ColumnVisibilityMenu } from './column-menu';
import { DataTableBody, type DataTableBodyGroup } from './data-table-body';
import {
  columnAlign,
  groupKeyOf,
  groupRows,
  paginate,
  selectionState,
  sortRows,
  toggleAll,
  toggleOne,
  type DataTableColumn,
  type DataTableGroupBy,
  type SortState,
} from './data-table-utils';
import { DensityToggle } from './density-toggle';
import { DEPLOYMENT_COLUMNS, DEPLOYMENT_ROWS } from './fixtures';

export interface DataTableProps<T> {
  rows?: readonly T[];
  columns?: ReadonlyArray<DataTableColumn<T>>;
  /** Stable row id (defaults to `row.id`). */
  getRowId?: (row: T) => string;
  /** Row name for checkbox and menu labels (defaults to the first column's value). */
  getRowLabel?: (row: T) => string;
  /** Table name (screen-reader caption unless `showCaption`). */
  caption?: string;
  showCaption?: boolean;

  /** Row selection with a select-all header checkbox (current page). */
  selectable?: boolean;
  selectedIds?: readonly string[];
  defaultSelectedIds?: readonly string[];
  onSelectionChange?: (ids: string[]) => void;
  /** Rendered in the toolbar while rows are selected. */
  bulkActions?: (selectedIds: string[]) => ReactNode;
  /**
   * Shows the "N selected" text in the toolbar while rows are selected (default true). Turn it
   * off when the page renders its own count, e.g. a BulkActionBar.
   */
  selectionSummary?: boolean;

  /** Row-actions menu items. */
  rowActions?: (row: T) => Array<MoreMenuAction | 'separator'>;

  sort?: SortState | null;
  defaultSort?: SortState | null;
  onSortChange?: (sort: SortState) => void;
  /** Rows arrive sorted (server side): headers still toggle, rows are not re-sorted. */
  manualSorting?: boolean;

  /** Client-side pagination; false shows every row. */
  paginated?: boolean;
  defaultPageSize?: number;
  pageSizeOptions?: readonly number[];

  /** Controlled row density. */
  density?: TableDensity;
  /** Initial density; omitted, the table follows the surrounding DensityProvider (comfortable outside one). */
  defaultDensity?: TableDensity;
  onDensityChange?: (density: TableDensity) => void;
  showDensityToggle?: boolean;
  showColumnMenu?: boolean;

  loading?: boolean;
  loadingRows?: number;
  emptyState?: ReactNode;
  /**
   * Groups rows under header rows (a field key or a function returning the group key). Groups keep
   * the order in which their keys first appear in `rows`; sorting applies inside each group, and
   * pagination pages through the grouped rows (each header shows the group's full count).
   */
  groupBy?: DataTableGroupBy<T>;
  /** Header text of a group (default: the key, or "No group" for rows without a value). */
  groupLabel?: (key: string, rows: readonly T[]) => ReactNode;
  /** Group headers render a keyboard-accessible collapse button (default true). */
  collapsibleGroups?: boolean;
  /** Controlled collapsed group keys. */
  collapsedGroups?: readonly string[];
  /** Group keys collapsed initially. */
  defaultCollapsedGroups?: readonly string[];
  onCollapsedGroupsChange?: (keys: string[]) => void;

  /** Left side of the toolbar (title, search, FilterBar…). */
  toolbar?: ReactNode;
  className?: string;
}

const defaultRowId = (row: unknown): string => {
  const id = (row as { id?: unknown }).id;
  return typeof id === 'string' || typeof id === 'number' ? String(id) : '';
};

/**
 * Generic data table on the kit Table: typed columns, sortable headers (aria-sort), row selection
 * with select-all / indeterminate, column visibility menu, density toggle, row actions, loading
 * and empty states, client-side sort + pagination, and optional collapsible row groups (`groupBy`).
 */
export function DataTable<T = (typeof DEPLOYMENT_ROWS)[number]>({
  rows = DEPLOYMENT_ROWS as unknown as readonly T[],
  columns = DEPLOYMENT_COLUMNS as unknown as ReadonlyArray<DataTableColumn<T>>,
  getRowId = defaultRowId,
  getRowLabel,
  caption = 'Deployments',
  showCaption = false,
  selectable = true,
  selectedIds,
  defaultSelectedIds = [],
  onSelectionChange,
  bulkActions,
  selectionSummary = true,
  rowActions,
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  manualSorting = false,
  paginated = true,
  defaultPageSize = 10,
  pageSizeOptions = [10, 25, 50],
  density: densityProp,
  defaultDensity,
  onDensityChange,
  showDensityToggle = true,
  showColumnMenu = true,
  loading = false,
  loadingRows = 5,
  emptyState,
  groupBy,
  groupLabel,
  collapsibleGroups = true,
  collapsedGroups: collapsedProp,
  defaultCollapsedGroups = [],
  onCollapsedGroupsChange,
  toolbar,
  className,
}: DataTableProps<T>) {
  const { t } = useI18n();
  const [innerSort, setInnerSort] = useState<SortState | null>(defaultSort);
  const [innerSelected, setInnerSelected] = useState<ReadonlySet<string>>(() => new Set(defaultSelectedIds));
  const [innerDensity, setInnerDensity] = useState<TableDensity | null>(defaultDensity ?? null);
  const contextDensity = useDensity();
  const [hidden, setHidden] = useState<ReadonlySet<string>>(() => new Set(columns.filter((c) => c.defaultHidden).map((c) => c.id)));
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(defaultPageSize);

  const sort = sortProp === undefined ? innerSort : sortProp;
  const selected: ReadonlySet<string> = selectedIds ? new Set(selectedIds) : innerSelected;
  const density = densityProp ?? innerDensity ?? contextDensity;
  const visibleColumns = columns.filter((c) => !hidden.has(c.id));
  const labelOf =
    getRowLabel ??
    ((row: T) => {
      const first = columns[0];
      const value = first?.accessor?.(row);
      return value == null ? getRowId(row) : String(value);
    });

  const [innerCollapsed, setInnerCollapsed] = useState<ReadonlySet<string>>(() => new Set(defaultCollapsedGroups));
  const collapsed: ReadonlySet<string> = collapsedProp ? new Set(collapsedProp) : innerCollapsed;

  const sortedRows = manualSorting ? [...rows] : sortRows(rows, columns, sort);
  const allGroups = groupBy ? groupRows(sortedRows, groupBy, rows) : null;
  const sorted = allGroups ? allGroups.flatMap((g) => g.rows) : sortedRows;
  const pageRows = paginated ? paginate(sorted, page, pageSize) : sorted;
  // Rows in collapsed groups are hidden, so select-all leaves them alone.
  const pageIds = (groupBy ? pageRows.filter((row) => !collapsed.has(groupKeyOf(row, groupBy))) : pageRows).map(getRowId);
  const header = selectionState(pageIds, selected);
  const selectedList = rows.map(getRowId).filter((id) => selected.has(id));

  const setSelected = (next: Set<string>) => {
    setInnerSelected(next);
    onSelectionChange?.(rows.map(getRowId).filter((id) => next.has(id)));
  };
  const changeSort = (columnId: string, direction: SortState['direction']) => {
    const next: SortState = { columnId, direction: sort?.columnId === columnId ? direction : 'ascending' };
    setInnerSort(next);
    onSortChange?.(next);
    setPage(1);
  };
  const toggleGroup = (key: string) => {
    const next = new Set(collapsed);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    setInnerCollapsed(next);
    onCollapsedGroupsChange?.([...next]);
  };
  const nameOf = (key: string) => key || 'No group';
  const bodyGroups: Array<DataTableBodyGroup<T>> | undefined =
    groupBy && allGroups
      ? allGroups
          .map((g) => ({
            key: g.key,
            label: groupLabel ? groupLabel(g.key, g.rows) : nameOf(g.key),
            name: nameOf(g.key),
            rows: pageRows.filter((row) => groupKeyOf(row, groupBy) === g.key),
            ids: g.rows.map(getRowId),
          }))
          .filter((g) => g.rows.length > 0)
      : undefined;

  const changeDensity = (next: TableDensity) => {
    setInnerDensity(next);
    onDensityChange?.(next);
  };
  const toggleColumn = (id: string, visible: boolean) =>
    setHidden((prev) => {
      const next = new Set(prev);
      if (visible) next.delete(id);
      else next.add(id);
      return next;
    });

  const hasSelection = selectable && selectedList.length > 0 && (selectionSummary || bulkActions != null);
  const showToolbar = toolbar != null || showDensityToggle || showColumnMenu || hasSelection;

  return (
    <div className={cn('overflow-hidden rounded-xl border border-border bg-card shadow-sm', className)}>
      {showToolbar && (
        <div
          className={cn(
            'flex min-h-12 flex-wrap items-center gap-2 border-b border-border px-3 py-2 transition-colors motion-reduce:transition-none',
            hasSelection ? 'bg-primary/8' : 'bg-secondary/30',
          )}
        >
          <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
            {hasSelection ? (
              <>
                {selectionSummary && (
                  <span className="text-[12.5px] font-semibold text-foreground" aria-live="polite">
                    {selectedList.length} selected
                  </span>
                )}
                {selectionSummary && bulkActions && <span aria-hidden className="h-4 w-px bg-border" />}
                {bulkActions?.(selectedList)}
              </>
            ) : (
              toolbar
            )}
          </div>
          <div className="flex items-center gap-2">
            {showDensityToggle && <DensityToggle value={density} onChange={changeDensity} />}
            {showColumnMenu && <ColumnVisibilityMenu columns={columns} hidden={hidden} onToggle={toggleColumn} />}
          </div>
        </div>
      )}
      {/* The toggle drives a density context for the table: its rows and the controls inside them. */}
      <DensityProvider density={density}>
        <Table aria-busy={loading || undefined}>
          <TableCaption srOnly={!showCaption}>{caption}</TableCaption>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              {selectable && (
                <TableHead className="w-10 pe-0">
                  <Checkbox
                    aria-label={t('table.selectAllPage')}
                    checked={header.checked}
                    indeterminate={header.indeterminate}
                    disabled={loading || pageIds.length === 0}
                    onCheckedChange={() => setSelected(toggleAll(pageIds, selected))}
                  />
                </TableHead>
              )}
              {visibleColumns.map((c) => (
                <TableHead
                  key={c.id}
                  align={columnAlign(c)}
                  className={c.headClassName}
                  sortable={c.sortable}
                  sortDirection={sort?.columnId === c.id ? sort.direction : 'none'}
                  onSortChange={(dir) => changeSort(c.id, dir)}
                >
                  {c.header}
                </TableHead>
              ))}
              {rowActions && (
                <TableHead className="w-12">
                  <span className="sr-only">{t('table.actions')}</span>
                </TableHead>
              )}
            </TableRow>
          </TableHeader>
          <DataTableBody
            rows={pageRows}
            columns={visibleColumns}
            getRowId={getRowId}
            getRowLabel={labelOf}
            selectable={selectable}
            selected={selected}
            onToggleRow={(id) => setSelected(toggleOne(id, selected))}
            rowActions={rowActions}
            loading={loading}
            loadingRows={loadingRows}
            emptyState={emptyState}
            groups={bodyGroups && bodyGroups.length > 0 ? bodyGroups : undefined}
            collapsedGroups={collapsed}
            collapsibleGroups={collapsibleGroups}
            onToggleGroup={toggleGroup}
            onToggleGroupRows={(ids) => setSelected(toggleAll(ids, selected))}
          />
        </Table>
      </DensityProvider>
      {loading && (
        <p role="status" className="sr-only">
          Loading {caption.toLowerCase()}…
        </p>
      )}
      {paginated && !loading && rows.length > 0 && (
        <PaginationFooter
          className="border-t border-border px-4 py-3"
          total={rows.length}
          page={page}
          onPageChange={setPage}
          pageSize={pageSize}
          onPageSizeChange={setPageSize}
          pageSizeOptions={pageSizeOptions}
          noun={caption}
        />
      )}
    </div>
  );
}

import { ChevronDown, Columns3 } from '@gntik-ai/icons';
import { Button, Menu, MenuCheckboxItem, MenuContent, MenuGroup, MenuGroupLabel, MenuTrigger, useI18n } from '@gntik-ai/ui';
import type { DataTableColumn } from './data-table-utils';

export interface ColumnVisibilityMenuProps<T> {
  columns: ReadonlyArray<DataTableColumn<T>>;
  hidden: ReadonlySet<string>;
  onToggle: (columnId: string, visible: boolean) => void;
  label?: string;
}

/** "Columns" menu: one checkbox item per hideable column. The last visible column cannot be hidden. */
export function ColumnVisibilityMenu<T>({ columns, hidden, onToggle, label: labelProp }: ColumnVisibilityMenuProps<T>) {
  const { t } = useI18n();
  const label = labelProp ?? t('table.columns');
  const visibleCount = columns.filter((c) => !hidden.has(c.id)).length;
  return (
    <Menu>
      <MenuTrigger render={<Button variant="secondary" size="sm" icon={Columns3} trailingIcon={ChevronDown} />}>{label}</MenuTrigger>
      <MenuContent align="end" className="min-w-[200px]">
        <MenuGroup>
          <MenuGroupLabel>{t('table.visibleColumns')}</MenuGroupLabel>
          {columns
            .filter((c) => c.hideable !== false)
            .map((c) => {
              const visible = !hidden.has(c.id);
              return (
                <MenuCheckboxItem
                  key={c.id}
                  checked={visible}
                  disabled={visible && visibleCount <= 1}
                  onCheckedChange={(on) => onToggle(c.id, on)}
                >
                  {c.header}
                </MenuCheckboxItem>
              );
            })}
        </MenuGroup>
      </MenuContent>
    </Menu>
  );
}

import { ChevronRight, Inbox } from '@gntik-ai/icons';
import { Checkbox, cn, EmptyState, MoreMenu, Skeleton, TableBody, TableCell, TableHead, TableRow, type MoreMenuAction, useI18n } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import { COLUMN_VARIANT_CLASSES, columnAlign, formatCell, selectionState, type DataTableColumn } from './data-table-utils';

/** A group as the body renders it: its rows on the current page plus header data. */
export interface DataTableBodyGroup<T> {
  key: string;
  /** Visible group name (header text). */
  label: ReactNode;
  /** Plain-text name for button and checkbox labels. */
  name: string;
  /** Rows of the group on the current page. */
  rows: readonly T[];
  /** Ids of every row in the group (all pages): the count and the group checkbox use them. */
  ids: readonly string[];
}

export interface DataTableBodyProps<T> {
  rows: readonly T[];
  columns: ReadonlyArray<DataTableColumn<T>>;
  getRowId: (row: T) => string;
  /** Label of a row for its checkbox and actions ("orders-api"). */
  getRowLabel: (row: T) => string;
  selectable: boolean;
  selected: ReadonlySet<string>;
  onToggleRow: (id: string) => void;
  rowActions?: (row: T) => Array<MoreMenuAction | 'separator'>;
  loading: boolean;
  loadingRows: number;
  emptyState?: ReactNode;
  /** Grouped rendering: one `<tbody>` per group with a header row (replaces `rows`). */
  groups?: ReadonlyArray<DataTableBodyGroup<T>>;
  /** Keys of collapsed groups. */
  collapsedGroups?: ReadonlySet<string>;
  /** Group headers render a collapse button (default true). */
  collapsibleGroups?: boolean;
  onToggleGroup?: (key: string) => void;
  /** Selects or clears every row of a group. */
  onToggleGroupRows?: (ids: readonly string[]) => void;
}

const groupHeadClass = 'h-9 bg-secondary/50 text-[12.5px] font-semibold tracking-normal normal-case text-foreground';

/** Body rows, plus the loading (skeleton rows) and empty (EmptyState) states. */
export function DataTableBody<T>({
  rows,
  columns,
  getRowId,
  getRowLabel,
  selectable,
  selected,
  onToggleRow,
  rowActions,
  loading,
  loadingRows,
  emptyState,
  groups,
  collapsedGroups,
  collapsibleGroups = true,
  onToggleGroup,
  onToggleGroupRows,
}: DataTableBodyProps<T>) {
  const { t } = useI18n();
  const span = columns.length + (selectable ? 1 : 0) + (rowActions ? 1 : 0);
  if (loading) {
    return (
      <TableBody>
        {Array.from({ length: loadingRows }, (_, i) => (
          <TableRow key={`loading-${i}`}>
            {selectable && (
              <TableCell className="w-10">
                <Skeleton className="size-4 rounded-[4px]" />
              </TableCell>
            )}
            {columns.map((c) => (
              <TableCell key={c.id} align={columnAlign(c)}>
                <Skeleton className={cn('h-3.5', columnAlign(c) === 'right' ? 'ms-auto w-16' : 'w-24')} />
              </TableCell>
            ))}
            {rowActions && <TableCell className="w-12" />}
          </TableRow>
        ))}
      </TableBody>
    );
  }
  if (rows.length === 0) {
    return (
      <TableBody>
        <TableRow className="hover:bg-transparent">
          <TableCell colSpan={span} className="py-10">
            {emptyState ?? <EmptyState icon={Inbox} size="sm" title={t('common.noResults')} description={t('table.emptyDescription')} />}
          </TableCell>
        </TableRow>
      </TableBody>
    );
  }
  const renderRow = (row: T) => {
    const id = getRowId(row);
    const isSelected = selected.has(id);
    const label = getRowLabel(row);
    return (
      <TableRow key={id} selected={selectable && isSelected}>
        {selectable && (
          <TableCell className="w-10 pe-0">
            <Checkbox aria-label={t('table.selectRow', { label })} checked={isSelected} onCheckedChange={() => onToggleRow(id)} />
          </TableCell>
        )}
        {columns.map((c) => (
          <TableCell key={c.id} align={columnAlign(c)} className={cn('whitespace-nowrap', COLUMN_VARIANT_CLASSES[c.variant ?? 'default'], c.className)}>
            {c.cell ? c.cell(row) : formatCell(c.accessor?.(row))}
          </TableCell>
        ))}
        {rowActions && (
          <TableCell align="right" className="w-12 py-0">
            <MoreMenu items={rowActions(row)} label={t('table.rowActions', { label })} variant="ghost" size="sm" />
          </TableCell>
        )}
      </TableRow>
    );
  };
  if (!groups) return <TableBody>{rows.map(renderRow)}</TableBody>;
  return (
    <>
      {groups.map((group, gi) => {
        const open = !collapsedGroups?.has(group.key);
        const state = selectionState(group.ids, selected);
        const count = group.ids.length;
        const heading = (
          <>
            <span className="truncate">{group.label}</span>{' '}
            <span className="rounded-full bg-secondary px-1.5 font-mono text-[11px] font-medium text-muted-foreground tabular-nums">
              {count}
            </span>{' '}
            <span className="sr-only">{count === 1 ? 'row' : 'rows'}</span>
          </>
        );
        return (
          <TableBody
            key={group.key}
            data-group={group.key}
            // Every group but the last keeps the bottom rule of its last row.
            className={gi < groups.length - 1 ? '[&>tr:last-child>td]:border-b' : undefined}
          >
            <TableRow className="hover:bg-transparent">
              {selectable && (
                <TableCell className={cn('w-10 pe-0', groupHeadClass)}>
                  <Checkbox
                    aria-label={t('table.selectRow', { label: `all in ${group.name}` })}
                    checked={state.checked}
                    indeterminate={state.indeterminate}
                    disabled={count === 0}
                    onCheckedChange={() => onToggleGroupRows?.(group.ids)}
                  />
                </TableCell>
              )}
              <TableHead scope="rowgroup" colSpan={span - (selectable ? 1 : 0)} className={cn(groupHeadClass, collapsibleGroups && 'ps-2')}>
                {collapsibleGroups ? (
                  <button
                    type="button"
                    aria-expanded={open}
                    onClick={() => onToggleGroup?.(group.key)}
                    className="inline-flex max-w-full items-center gap-1.5 rounded-sm px-1 py-0.5 hover:bg-secondary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring"
                  >
                    <ChevronRight size={14} aria-hidden className={cn('shrink-0 text-muted-foreground transition-transform motion-reduce:transition-none', open ? 'rotate-90' : 'rtl:-scale-x-100')} />
                    {heading}
                  </button>
                ) : (
                  <span className="inline-flex max-w-full items-center gap-1.5">{heading}</span>
                )}
              </TableHead>
            </TableRow>
            {open && group.rows.map(renderRow)}
          </TableBody>
        );
      })}
    </>
  );
}

import type { ReactNode } from 'react';

export type SortDirectionValue = 'ascending' | 'descending';
export type CellValue = string | number | boolean | Date | null | undefined;

export type DataTableColumnVariant = 'default' | 'mono' | 'muted' | 'numeric';

/** Body-cell classes of each column variant. */
export const COLUMN_VARIANT_CLASSES: Record<DataTableColumnVariant, string> = {
  default: '',
  mono: 'font-mono text-[12px]',
  muted: 'text-[12.5px] text-muted-foreground',
  numeric: 'font-mono text-[12.5px] tabular-nums',
};

/** Effective alignment of a column (numeric columns default to right). */
export function columnAlign<T>(column: DataTableColumn<T>): DataTableColumn<T>['align'] {
  return column.align ?? (column.variant === 'numeric' ? 'right' : undefined);
}

/** One typed column of a DataTable. */
export interface DataTableColumn<T> {
  /** Stable key (sorting, visibility). */
  id: string;
  /** Header text; also the column's name in the visibility menu. */
  header: string;
  /** Raw value: used to sort, and rendered when `cell` is absent. */
  accessor?: (row: T) => CellValue;
  /** Custom cell rendering. */
  cell?: (row: T) => ReactNode;
  sortable?: boolean;
  align?: 'left' | 'right' | 'center';
  /** Can be hidden from the column menu (default true). */
  hideable?: boolean;
  /** Hidden until turned on in the column menu. */
  defaultHidden?: boolean;
  /**
   * Presentational preset for the body cells: `mono` (monospace ids, regions), `muted`
   * (secondary text), `numeric` (monospace tabular figures, right-aligned unless `align` is set).
   */
  variant?: DataTableColumnVariant;
  /** Classes for the body cells (merged after the variant's). */
  className?: string;
  /** Classes for the header cell (e.g. a width). */
  headClassName?: string;
}

export interface SortState {
  columnId: string;
  direction: SortDirectionValue;
}

/** Compares two cell values: nulls last, numbers and dates numerically, strings with localeCompare (numeric). */
export function compareValues(a: CellValue, b: CellValue): number {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  const na = a instanceof Date ? a.getTime() : a;
  const nb = b instanceof Date ? b.getTime() : b;
  if (typeof na === 'number' && typeof nb === 'number') return na - nb;
  if (typeof na === 'boolean' && typeof nb === 'boolean') return Number(na) - Number(nb);
  return String(na).localeCompare(String(nb), undefined, { numeric: true, sensitivity: 'base' });
}

/** Client-side sort (stable). Returns the input order when there is no sort or the column has no accessor. */
export function sortRows<T>(rows: readonly T[], columns: ReadonlyArray<DataTableColumn<T>>, sort: SortState | null): T[] {
  const column = sort ? columns.find((c) => c.id === sort.columnId) : undefined;
  if (!sort || !column?.accessor) return [...rows];
  const get = column.accessor;
  const sign = sort.direction === 'ascending' ? 1 : -1;
  return rows
    .map((row, index) => ({ row, index }))
    .sort((x, y) => {
      const va = get(x.row);
      const vb = get(y.row);
      // Nulls stay last in both directions.
      if (va == null || vb == null) return compareValues(va, vb) || x.index - y.index;
      return sign * compareValues(va, vb) || x.index - y.index;
    })
    .map(({ row }) => row);
}

/** Number of pages for a row count (at least 1). */
export function pageCountOf(total: number, pageSize: number): number {
  return Math.max(1, Math.ceil(total / Math.max(1, pageSize)));
}

/** Client-side pagination: the rows of a 1-based page (clamped to the valid range). */
export function paginate<T>(rows: readonly T[], page: number, pageSize: number): T[] {
  const last = pageCountOf(rows.length, pageSize);
  const p = Math.min(Math.max(1, page), last);
  return rows.slice((p - 1) * pageSize, p * pageSize);
}

/** Header checkbox state for the rows on screen. */
export function selectionState(visibleIds: readonly string[], selected: ReadonlySet<string>): { checked: boolean; indeterminate: boolean } {
  const count = visibleIds.filter((id) => selected.has(id)).length;
  return { checked: count > 0 && count === visibleIds.length, indeterminate: count > 0 && count < visibleIds.length };
}

/** Selects all of `ids` when not all are selected; otherwise clears them. Other selections are kept. */
export function toggleAll(ids: readonly string[], selected: ReadonlySet<string>): Set<string> {
  const next = new Set(selected);
  const all = ids.length > 0 && ids.every((id) => selected.has(id));
  for (const id of ids) {
    if (all) next.delete(id);
    else next.add(id);
  }
  return next;
}

export function toggleOne(id: string, selected: ReadonlySet<string>): Set<string> {
  const next = new Set(selected);
  if (next.has(id)) next.delete(id);
  else next.add(id);
  return next;
}

/** Default cell text for a raw value. */
export function formatCell(value: CellValue): ReactNode {
  if (value == null) return '—';
  if (value instanceof Date) return value.toLocaleDateString();
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  return value;
}

/** Groups rows by a field key or by a function returning the group key. */
export type DataTableGroupBy<T> = Extract<keyof T, string> | ((row: T) => string | number | null | undefined);

/** One group of rows, in display order. */
export interface DataTableGroup<T> {
  /** Group key (`''` for rows without a value). */
  key: string;
  rows: T[];
}

/** Group key of a row (`''` when the value is null or undefined). */
export function groupKeyOf<T>(row: T, groupBy: DataTableGroupBy<T>): string {
  const value = typeof groupBy === 'function' ? groupBy(row) : (row as Record<string, unknown>)[groupBy];
  return value == null ? '' : String(value);
}

/**
 * Splits rows into groups, keeping the row order inside each group. Groups follow `order` (the
 * keys' first appearance in it, e.g. the unsorted input) and then any key not seen there.
 */
export function groupRows<T>(rows: readonly T[], groupBy: DataTableGroupBy<T>, order: readonly T[] = rows): DataTableGroup<T>[] {
  const groups = new Map<string, T[]>();
  for (const row of order) {
    const key = groupKeyOf(row, groupBy);
    if (!groups.has(key)) groups.set(key, []);
  }
  for (const row of rows) {
    const key = groupKeyOf(row, groupBy);
    const list = groups.get(key);
    if (list) list.push(row);
    else groups.set(key, [row]);
  }
  return [...groups].filter(([, list]) => list.length > 0).map(([key, list]) => ({ key, rows: list }));
}

import { Rows2, Rows3 } from '@gntik-ai/icons';
import { Toggle, ToggleGroup, type TableDensity, useI18n } from '@gntik-ai/ui';

export interface DensityToggleProps {
  value: TableDensity;
  onChange: (density: TableDensity) => void;
}

/** Two-icon segmented control: comfortable or compact rows. */
export function DensityToggle({ value, onChange }: DensityToggleProps) {
  const { t } = useI18n();
  return (
    <ToggleGroup
      aria-label={t('table.density')}
      size="sm"
      value={[value]}
      onValueChange={(v) => {
        const next = v[0];
        if (next === 'compact' || next === 'comfortable') onChange(next);
      }}
    >
      <Toggle value="comfortable" iconOnly aria-label={t('table.comfortable')}>
        <Rows2 size={15} aria-hidden />
      </Toggle>
      <Toggle value="compact" iconOnly aria-label={t('table.compact')}>
        <Rows3 size={15} aria-hidden />
      </Toggle>
    </ToggleGroup>
  );
}

